-- 서비스가 이렇게 된다

public List<Member> 검색(String username, Integer age, String teamName) {
    boolean u = username != null;
    boolean a = age != null;
    boolean t = teamName != null;

    if (u && a && t) return repo.findByUsernameAndAgeAndTeamName(
            username, age, teamName);
    if (u && a)      return repo.findByUsernameAndAge(username, age);
    if (u && t)      return repo.findByUsernameAndTeamName(username, teamName);
    if (a && t)      return repo.findByAgeAndTeamName(age, teamName);
    if (u)           return repo.findByUsername(username);
    if (a)           return repo.findByAge(age);
    if (t)           return repo.findByTeamName(teamName);
    return repo.findAll();
}

